<script>(()=>{'use strict';
const host=document.getElementById('lsez-atlas');if(!host||host.shadowRoot)return;const root=host.attachShadow({mode:'open'});root.append(document.getElementById('lsez-atlas-template').content.cloneNode(true));
const $=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STATUS={available:'Piedāvājumā avotā',occupied:'Aizņemts avotā',reserved:'Rezervēts*',unknown:'Nav publicētu datu'};
const money=n=>new Intl.NumberFormat('lv-LV',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const num=(n,d=0)=>new Intl.NumberFormat('lv-LV',{maximumFractionDigits:d}).format(n);
const estimate=(p,s)=>p.kind==='building'||p.priceEligible===false?null:Math.round(Math.max(0,Number(p.area)||0)*s.rate*s.factor);
const effectiveStatus=(p,reservations,today)=>{const r=reservations[p.id];return r&&(!r.until||r.until>=today)&&p.kind==='land'&&p.status!=='occupied'?'reserved':p.status||'unknown';};
function filterObjects(objects,f,s,reservations,today){
 const q=f.search.trim().toLocaleLowerCase('lv');
 return objects.filter(o=>{const p=o.properties;const price=estimate(p,s);return(!q||[p.name,p.street,p.cadastre,p.label,p.buildingType,p.parkName].join(' ').toLocaleLowerCase('lv').includes(q))&&(f.status==='all'||effectiveStatus(p,reservations,today)===f.status)&&(f.maxArea==null||p.area<=f.maxArea)&&(p.kind==='building'||f.budget==null||price<=f.budget)&&(f.zone==='all'||(f.zone==='unknown'?!p.zone:(p.zone||'').includes(f.zone)))&&(!f.detailed||p.exact);}).sort((a,b)=>{
 const x=a.properties,y=b.properties;
 if(f.sort==='area-asc')return x.area-y.area;if(f.sort==='area-desc')return y.area-x.area;
 if(f.sort==='price-asc')return(estimate(x,s)||0)-(estimate(y,s)||0);
 return Number(y.status==='available')-Number(x.status==='available')||Number(y.exact)-Number(x.exact)||x.name.localeCompare(y.name,'lv',{numeric:true});
 });
}
function makeCSV(objects,s,reservations,today){const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';const rows=[['Objekts','Apgabals','Veids','Platība m²','Platības avots','Pieejamība','Cenas scenārijs EUR','Cenas veids','Kadastra apzīmējums pēc avota','Kontūras piezīme','Avots']];for(const o of objects){const p=o.properties;rows.push([p.name,p.parkName||p.park,p.kind==='building'?'Ēkas kontūra':'Zemes / teritorijas kontūra',p.area,p.areaSource,STATUS[effectiveStatus(p,reservations,today)],estimate(p,s),p.kind==='building'?'Nav aprēķināts':'Lietotāja scenārijs, nav oficiāla cena',p.cadastre,p.geometryNote,p.source]);}return '\uFEFF'+rows.map(r=>r.map(quote).join(';')).join('\r\n');}

const REGIONS=JSON.parse($('#atlas-region-data').textContent),GEO=JSON.parse($('#atlas-regional-geodata').textContent),STYLE=JSON.parse($('#atlas-map-style').textContent);
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Piezīmes paliks šajā sesijā: pārlūks neļauj tās saglabāt.')}};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Riga',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let settings=read('lsez-price-v1',{rate:12,factor:1});if(!Number.isFinite(settings.rate)||settings.rate<0||!Number.isFinite(settings.factor)||settings.factor<=0)settings={rate:12,factor:1};
let reservations=read('lsez-reservations-v1',{}),comparison=read('lsez-compare-v1',[]);
const catalog=new Map();for(const r of REGIONS)for(const type of ['land','buildings'])for(const o of GEO[r.id][type].features){o.properties.parkName=r.name;catalog.set(o.properties.id,o);}
comparison=Array.isArray(comparison)?comparison.filter(id=>catalog.has(id)).slice(0,3):[];
